// Mock sports API (/api/mock-sports/v1): match files in the same structure as the bundled
// deep-data mocks (data/mock/<competition>/<id>.json), generated by shared/utils/match-sim.ts.

export interface MatchFileTeam {
  id: string
  name: string
  shortName: string
  abbr: string
  score: number
  halfTimeScore: number
  redCards: number
}

export interface MatchFileGoal {
  goalType: 'Goal' | 'Penalty' | 'Own'
  period: 'FirstHalf' | 'SecondHalf'
  assistPlayerId: string | null
  time: string
  playerId: string
  timestamp: string
  player: string
  assist?: string
}

export interface MatchFileCard { period: 'FirstHalf' | 'SecondHalf', time: string, type: 'Yellow' | 'Red', playerId: string, timestamp: string, player: string }

export interface MatchFileSub {
  period: 'FirstHalf' | 'SecondHalf'
  playerOnId: string
  playerOffId: string
  time: string
  timestamp: string
  playerOn: string
  playerOff: string
}

export interface MatchFileSide { team: string, goals: MatchFileGoal[], cards: MatchFileCard[], substitutions: MatchFileSub[] }

export interface MatchFilePlayer { id: string, name: string, shirtNumber: number, position: 'Goalkeeper' | 'Defender' | 'Midfielder' | 'Forward', isCaptain: boolean }

export interface MatchFileLineup {
  teamId: string
  team: string
  formation: string
  formationRows: string[][]
  manager: string
  startingXI: MatchFilePlayer[]
  substitutes: MatchFilePlayer[]
}

export type MatchFilePair = { home: number, away: number }

export interface MatchFileEvent { minute: string, type: string, team: string | null, player1: string | null, player2: string | null }

export interface MatchFile {
  source: {
    name: string
    url?: string
    scrapedAt?: string
    note?: string
    /** Set on generated files: everything but the result is made up. */
    simulated?: boolean
    seed?: string
  }
  matchInfo: {
    matchId: string
    competition: string
    season: string
    matchWeek?: number
    kickoff: string
    kickoffTimezone: string
    venue?: string
    attendance?: number
    status: 'FullTime'
    resultType: 'NormalResult'
    homeTeam: MatchFileTeam
    awayTeam: MatchFileTeam
    officials: Array<{ role: string, name: string }>
  }
  keyEvents: { home: MatchFileSide, away: MatchFileSide }
  lineups: { home: MatchFileLineup, away: MatchFileLineup }
  stats: {
    summary: Record<string, MatchFilePair>
    extra: { home: Record<string, number>, away: Record<string, number> }
  }
  events: MatchFileEvent[]
}

/** One row of GET /api/mock-sports/v1/matches. */
export interface MockSportsMatchSummary {
  id: string
  competition: string
  kickoff: string
  createdAt: string
  home: string
  away: string
  score: MatchFilePair
  /** football-data id of the real fixture whose result the simulation keeps. */
  fixtureId: string
}
